73	// SG_TUNED_UNROLL-parameterized scalar grid-stride kernel; calls the canonical
74	// per-element grokadamw_step (math single-sourced in algorithms/grokadamw.h).
75	template <typename ParamT, typename GradT, int UNROLL>
76	__global__ void __launch_bounds__(SG_TUNED_BLOCK_SIZE, SG_GROKADAMW_MIN_BLOCKS)
77	grokadamw_kernel(
78	    ParamT* param, float* exp_avg, float* exp_avg_sq, float* ema,
79	    const GradT* grad,
80	    float alpha, float lamb,
81	    float lr, float beta1, float beta2, float eps, float wd,
82	    float bc1, float bc2, int64_t N
83	) {
84	    const int64_t stride = prim::grid_stride() * UNROLL;
85	    const int64_t base0 = prim::grid_stride_index() * UNROLL;
86	    for (int64_t base = base0; base < N; base += stride) {
87	        #pragma unroll
88	        for (int u = 0; u < UNROLL; ++u) {
89	            const int64_t i = base + u;
90	            if (i < N) {
91	                SG_SANITIZE_GRAD_INPLACE(grad, i);
92	                grokadamw_step(param, exp_avg, exp_avg_sq, ema, grad,
93	                               alpha, lamb, lr, beta1, beta2, eps, wd,
94	                               bc1, bc2, i);
95	            }
96	        }
97	    }
98	}
