130	void launch_grokadamw_step(
131	    torch::Tensor& param,
132	    torch::Tensor& exp_avg,
133	    torch::Tensor& exp_avg_sq,
134	    torch::Tensor& ema,
135	    const torch::Tensor& grad,
136	    float alpha, float lamb,
137	    float lr, float beta1, float beta2, float eps, float wd,
138	    float bc1, float bc2
139	) {
140	    const int64_t N = param.numel();
141	    if (N == 0) return;
142	
143	    auto stream = at::cuda::getCurrentCUDAStream().stream();
144	
145	    // §6.1: keep the Adam moments (m, v) L2-resident across the step.
146	    prim::L2PersistScope l2(stream,
147	        exp_avg.data_ptr(), exp_avg.nbytes(),
148	        exp_avg_sq.data_ptr(), exp_avg_sq.nbytes());
149	
150	    const int block = SG_TUNED_BLOCK_SIZE;
151	    const int grid = static_cast<int>(
152	        std::min<int64_t>(65535, (N + block - 1) / block));
153	
154	    const bool all_fp32 = param.scalar_type() == torch::kFloat32 &&
155	                          grad.scalar_type() == torch::kFloat32;
156	
157	    if (SG_TUNED_VEC_WIDTH == 4 && all_fp32 &&
158	        prim::is_vec4_alignable(param.data_ptr(), N) &&
159	        prim::is_vec4_alignable(exp_avg.data_ptr(), N) &&
160	        prim::is_vec4_alignable(exp_avg_sq.data_ptr(), N) &&
161	        prim::is_vec4_alignable(ema.data_ptr(), N) &&
162	        prim::is_vec4_alignable(grad.data_ptr(), N)) {
163	        const int64_t N4 = N / 4;
164	        const int grid4 = static_cast<int>(
165	            std::min<int64_t>(65535, (N4 + block - 1) / block));
166	        grokadamw_kernel_vec4_fp32<<<grid4, block, 0, stream>>>(
167	            reinterpret_cast<float4*>(param.data_ptr<float>()),
168	            reinterpret_cast<float4*>(exp_avg.data_ptr<float>()),
169	            reinterpret_cast<float4*>(exp_avg_sq.data_ptr<float>()),
170	            reinterpret_cast<float4*>(ema.data_ptr<float>()),
171	            reinterpret_cast<const float4*>(grad.data_ptr<float>()),
172	            alpha, lamb, lr, beta1, beta2, eps, wd, bc1, bc2, N4);
173	        SG_LAUNCH_CHECK(stream);
174	        return;
175	    }
176	
177	    AT_DISPATCH_FLOATING_TYPES_AND2(
178	        at::ScalarType::Half, at::ScalarType::BFloat16,
179	        param.scalar_type(), "grokadamw_step", [&] {
180	            grokadamw_kernel<scalar_t, scalar_t, SG_TUNED_UNROLL>
181	                <<<grid, block, 0, stream>>>(
182	                param.data_ptr<scalar_t>(),
183	                exp_avg.data_ptr<float>(),
184	                exp_avg_sq.data_ptr<float>(),
185	                ema.data_ptr<float>(),
186	                grad.data_ptr<scalar_t>(),
187	                alpha, lamb, lr, beta1, beta2, eps, wd, bc1, bc2, N);
188	            SG_LAUNCH_CHECK(stream);
189	        });
190	}
