206	void launch_fused_grokadamw_clip_step(
207	    torch::Tensor param, torch::Tensor exp_avg, torch::Tensor exp_avg_sq,
208	    torch::Tensor ema, torch::Tensor grad,
209	    float alpha, float lamb,
210	    float beta1, float beta2,
211	    float lr, float weight_decay, float eps,
212	    float bc1, float bc2, float clip_threshold
213	) {
214	    if (clip_threshold > 0.0f) {
215	        auto gn = grad.norm().item<float>();
216	        if (gn > clip_threshold) {
217	            grad = grad.mul(clip_threshold / gn);
218	        }
219	    }
220	    launch_grokadamw_step(param, exp_avg, exp_avg_sq, ema, grad,
221	                          alpha, lamb, lr, beta1, beta2, eps, weight_decay,
222	                          bc1, bc2);
223	}
