307	void launch_multi_tensor_grokadamw(
308	    std::vector<torch::Tensor>& params,
309	    std::vector<torch::Tensor>& exp_avgs,
310	    std::vector<torch::Tensor>& exp_avg_sqs,
311	    std::vector<torch::Tensor>& emas,
312	    std::vector<torch::Tensor>& grads,
313	    std::vector<float>& bc1s, std::vector<float>& bc2s,
314	    float alpha, float lamb,
315	    float beta1, float beta2,
316	    float lr, float wd, float eps
317	) {
318	    for (size_t i = 0; i < params.size(); i++) {
319	        launch_grokadamw_step(params[i], exp_avgs[i], exp_avg_sqs[i],
320	                              emas[i], grads[i],
321	                              alpha, lamb, lr, beta1, beta2, eps, wd,
322	                              bc1s[i], bc2s[i]);
323	    }
324	}
