326	// AdamW is GrokAdamW with lamb=0 (EMA amplification disabled).
327	// The ema buffer is not needed; allocate a dummy per-tensor.
328	void launch_fused_adamw_simple(
329	    std::vector<torch::Tensor>& params,
330	    std::vector<torch::Tensor>& exp_avgs,
331	    std::vector<torch::Tensor>& exp_avg_sqs,
332	    std::vector<torch::Tensor>& grads,
333	    std::vector<int64_t>& steps,
334	    float beta1, float beta2, float lr, float wd, float eps
335	) {
336	    for (size_t t = 0; t < params.size(); t++) {
337	        const int64_t N = params[t].numel();
338	        if (N == 0 || !grads[t].defined()) continue;
339	        float bc1 = 1.0f - std::pow(beta1, static_cast<float>(steps[t]));
340	        float bc2 = 1.0f - std::pow(beta2, static_cast<float>(steps[t]));
341	        auto ema_dummy = torch::zeros_like(exp_avgs[t]);
342	        launch_grokadamw_step(params[t], exp_avgs[t], exp_avg_sqs[t],
343	                              ema_dummy, grads[t],
344	                              0.0f, 0.0f, lr, beta1, beta2, eps, wd,
345	                              bc1, bc2);
346	    }
347	}
