56	__global__ void __launch_bounds__(SG_TUNED_BLOCK_SIZE, SG_LOOKSAM_MIN_BLOCKS)
57	looksam_perturb_kernel(
58	    ParamT* param, ParamT* backup, const GradT* grad, float scale, int64_t N
59	) {
60	    const int64_t stride = prim::grid_stride();
61	    for (int64_t i = prim::grid_stride_index(); i < N; i += stride) {
62	        SG_SANITIZE_GRAD_INPLACE(grad, i);
63	        looksam_perturb_step(param, backup, grad, scale, i);
64	    }
