276	// Fused direction-adjust: grad = (1 - lambda) * grad + lambda * grad_norm * (v_dir * inv_norm)
277	__global__ void looksam_direction_adjust_kernel(
278	    float* grad, const float* v_dir,
279	    float inv_norm, float lambda, float grad_norm, int64_t N
280	) {
281	    const int64_t stride = prim::grid_stride();
282	    for (int64_t i = prim::grid_stride_index(); i < N; i += stride) {
283	        float g = grad[i];
284	        float d = v_dir[i] * inv_norm;
285	        grad[i] = (1.0f - lambda) * g + lambda * grad_norm * d;
286	    }
287	}
