307	// Reduce: results[0] = ||sam_grad - grad||, results[1] = ||grad||.
308	void launch_looksam_norm_reduce(
309	    torch::Tensor grad, torch::Tensor sam_grad,
310	    torch::Tensor results
311	) {
312	    auto diff = (sam_grad - grad).to(torch::kFloat32);
313	    auto dn = diff.norm();
314	    auto gn = grad.to(torch::kFloat32).norm();
315	    results[0] = dn;
316	    results[1] = gn;
317	}
