3	// Migrated from csrc/device/optimizers/sm_90/lion_sm90.cuh.
4	//
5	// Sign-based optimizer with interpolated momentum (EvoLved Sign Momentum):
6	//   update  = sign(beta1 * exp_avg + (1 - beta1) * grad)
7	//   param  -= lr * (update + wd * param)
8	//   exp_avg = beta2 * exp_avg + (1 - beta2) * grad
9	//
10	// Only one state tensor (momentum buffer). No second moment.
11	
12	#include "csrc/common/types.h"
13	#include "csrc/common/utils.cuh"
14	
15	namespace sg { namespace algorithms {
16	
17	template <typename ParamT, typename GradT>
18	__device__ __forceinline__ void lion_step(
19	    ParamT* __restrict__ param,
20	    float* __restrict__ exp_avg,
21	    const GradT* __restrict__ grad,
22	    const float lr,
23	    const float beta1,
24	    const float beta2,
25	    const float wd,
26	    const int64_t idx
27	) {
28	    const float g  = static_cast<float>(grad[idx]);
29	    const float ea = exp_avg[idx];
30	    const float p  = static_cast<float>(param[idx]);
31	
32	    const float interp = beta1 * ea + (1.0f - beta1) * g;
33	    const float s = (interp != 0.0f) ? copysignf(1.0f, interp) : 0.0f;
34	
35	    param[idx]   = static_cast<ParamT>(p - lr * (s + wd * p));
36	    exp_avg[idx] = beta2 * ea + (1.0f - beta2) * g;
37	}
38	
39	__device__ __forceinline__ void lion_step_vec4(
40	    float4* __restrict__ param4,
41	    float4* __restrict__ exp_avg4,
42	    const float4* __restrict__ grad4,
43	    const float lr,
44	    const float beta1,
45	    const float beta2,
46	    const float wd,
47	    const int64_t i
48	) {
49	    float4 p  = param4[i];
50	    float4 ea = exp_avg4[i];
51	    float4 g  = grad4[i];
52	
53	    float4 interp;
54	    interp.x = beta1 * ea.x + (1.0f - beta1) * g.x;
55	    interp.y = beta1 * ea.y + (1.0f - beta1) * g.y;
56	    interp.z = beta1 * ea.z + (1.0f - beta1) * g.z;
57	    interp.w = beta1 * ea.w + (1.0f - beta1) * g.w;
58	
59	    const float sx = (interp.x != 0.0f) ? copysignf(1.0f, interp.x) : 0.0f;
60	    const float sy = (interp.y != 0.0f) ? copysignf(1.0f, interp.y) : 0.0f;
61	    const float sz = (interp.z != 0.0f) ? copysignf(1.0f, interp.z) : 0.0f;
62	    const float sw = (interp.w != 0.0f) ? copysignf(1.0f, interp.w) : 0.0f;
63	
64	    p.x -= lr * (sx + wd * p.x);
65	    p.y -= lr * (sy + wd * p.y);
66	    p.z -= lr * (sz + wd * p.z);
67	    p.w -= lr * (sw + wd * p.w);
68	    param4[i] = p;
69	
70	    ea.x = beta2 * ea.x + (1.0f - beta2) * g.x;
71	    ea.y = beta2 * ea.y + (1.0f - beta2) * g.y;
72	    ea.z = beta2 * ea.z + (1.0f - beta2) * g.z;
73	    ea.w = beta2 * ea.w + (1.0f - beta2) * g.w;
74	    exp_avg4[i] = ea;
75	}
