381	// Per-tensor Prodigy step: d_lr is the current adaptive learning rate.
382	void launch_fused_prodigy_step(
383	    torch::Tensor param, torch::Tensor exp_avg, torch::Tensor exp_avg_sq,
384	    torch::Tensor s, torch::Tensor param_init, torch::Tensor grad,
385	    float lr, float d_lr, float beta1, float beta2,
386	    float weight_decay, float eps, float bc1, float bc2
387	) {
388	    auto d_t = torch::tensor({d_lr},
389	        torch::TensorOptions().device(param.device()).dtype(torch::kFloat32));
390	    auto r_partial = torch::zeros({1},
391	        torch::TensorOptions().device(param.device()).dtype(torch::kFloat32));
392	    auto s_partial = torch::zeros({1},
393	        torch::TensorOptions().device(param.device()).dtype(torch::kFloat32));
394	    launch_prodigy_step(param, exp_avg, exp_avg_sq, s, param_init, grad,
395	                        d_t, r_partial, s_partial, d_lr,
396	                        beta1, beta2, eps, weight_decay, bc1, bc2);
397	}
398	
399	// DLR reduction: numerator += <grad, param - param_init>,
400	// denominator += ||s|| * d + eps.
401	__global__ void __launch_bounds__(SG_TUNED_BLOCK_SIZE, SG_PRODIGY_MIN_BLOCKS)
402	prodigy_dlr_reduce_kernel(
403	    const float* grad, const float* param, const float* param_init,
404	    const float* s, float* numerator, float* denominator,
405	    float eps, int64_t N
406	) {
407	    float num_acc = 0.0f, den_acc = 0.0f;
408	    const int64_t stride = prim::grid_stride();
409	    for (int64_t i = prim::grid_stride_index(); i < N; i += stride) {
410	        num_acc += ::grokking::sm90::sg_sanitize_grad(grad[i]) *
411	                   (param[i] - param_init[i]);
412	        den_acc += fabsf(s[i]);
413	    }
414	    // Fused two-value block reduction → ONE atomicAdd per partial per block
415	    // (was a per-THREAD atomicAdd, i.e. blockDim.x * gridDim.x atomics).
416	    float num_block, den_block;
417	    prim::block_reduce_sum2_f32(num_acc, den_acc, num_block, den_block);
418	    if (threadIdx.x == 0) {
419	        atomicAdd(numerator, num_block);
420	        atomicAdd(denominator, den_block);
421	    }
422	}
423	
424	void launch_prodigy_dlr_reduce(
425	    torch::Tensor grad, torch::Tensor param, torch::Tensor param_init,
426	    torch::Tensor s, torch::Tensor numerator, torch::Tensor denominator,
427	    float eps
428	) {
429	    const int64_t N = grad.numel();
430	    if (N == 0) return;
431	    auto stream = at::cuda::getCurrentCUDAStream().stream();
432	    const int block = SG_TUNED_BLOCK_SIZE;
433	    const int grid = static_cast<int>(
434	        std::min<int64_t>(65535, (N + block - 1) / block));
435	    prodigy_dlr_reduce_kernel<<<grid, block, 0, stream>>>(
436	        grad.data_ptr<float>(), param.data_ptr<float>(),
437	        param_init.data_ptr<float>(), s.data_ptr<float>(),
438	        numerator.data_ptr<float>(), denominator.data_ptr<float>(),
439	        eps, N);
440	    SG_LAUNCH_CHECK(stream);
441	}
