269	void launch_muon_ns_combine_update_fused(
270	    torch::Tensor param, torch::Tensor X, torch::Tensor AX, torch::Tensor AAX,
271	    float a, float b, float c, float neg_lr_scale, float decay_factor
272	) {
273	    const int64_t N = param.numel();
274	    if (N == 0) return;
275	    auto stream = at::cuda::getCurrentCUDAStream().stream();
276	    const int block = SG_TUNED_BLOCK_SIZE;
277	    const int grid = static_cast<int>(
278	        std::min<int64_t>(65535, (N + block - 1) / block));
279	
280	    AT_DISPATCH_FLOATING_TYPES_AND2(
281	        at::ScalarType::Half, at::ScalarType::BFloat16,
282	        param.scalar_type(), "muon_ns_combine_update", [&] {
283	            muon_ns_combine_update_kernel<scalar_t><<<grid, block, 0, stream>>>(
284	                param.data_ptr<scalar_t>(),
285	                X.data_ptr<float>(), AX.data_ptr<float>(), AAX.data_ptr<float>(),
286	                a, b, c, neg_lr_scale, decay_factor, N);
287	            SG_LAUNCH_CHECK(stream);
288	        });
