265	// Meta-net forward: mu[i] = phi(grad[i], sharpness[i]); smart_grad = grad + alpha*mu
266	template <typename GradT>
267	__global__ void __launch_bounds__(SG_TUNED_BLOCK_SIZE, SG_SUPERGROK11_MIN_BLOCKS)
268	sg11_mu_metanet_kernel(
269	    float* mu, const GradT* grad, const float* sharpness,
270	    float* smart_grad, float alpha,
271	    const float* W1, const float* b1, const float* W2, float b2_scalar,
272	    float rescale, int64_t N
273	) {
274	    __shared__ float sW1[SG11_H * 2];
275	    __shared__ float sb1[SG11_H];
276	    __shared__ float sW2[SG11_H];
277	    sg11_stage_phi_weights<SG11_H>(W1, b1, W2, sW1, sb1, sW2);
278	
279	    const int64_t stride = prim::grid_stride();
280	    for (int64_t i = prim::grid_stride_index(); i < N; i += stride) {
281	        SG_SANITIZE_GRAD_INPLACE(grad, i);
282	        float g = static_cast<float>(grad[i]);
283	        float s = sharpness[i];
284	        float phi = sg11_phi_forward<SG11_H>(g, s, sW1, sb1, sW2, b2_scalar) * rescale;
285	        mu[i] = phi;
286	        smart_grad[i] = g + alpha * phi;
287	    }
288	}
